#!/usr/bin/env bash
# recipes/crate-enumflags2-derive--0-7-8/build.sh -- stage the enumflags2_derive 0.7.8 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/enumflags2_derive-0.7.8"
